<!doctype html><html lang="es"><head><meta charset="utf-8"><title>Comprobante de venta #{{ $venta->id_venta }}</title><style>body{font-family:DejaVu Sans,sans-serif;font-size:12px;color:#222}h1{font-size:20px;margin:0 0 4px}.logo{width:58px;height:58px;object-fit:cover;vertical-align:middle;margin-right:10px}.encabezado{border-bottom:2px solid #1d4ed8;padding-bottom:12px;margin-bottom:20px}.muted{color:#666}.datos{margin-bottom:18px}.datos td{padding:3px 18px 3px 0}table.detalle{width:100%;border-collapse:collapse}table.detalle th,table.detalle td{border-bottom:1px solid #ddd;padding:8px;text-align:left}table.detalle th{background:#eef4ff}.numero{text-align:right;font-size:16px;font-weight:bold}.total{text-align:right;font-weight:bold;font-size:15px;padding-top:12px}.nota{margin-top:35px;color:#666;font-size:10px}</style></head><body>@php($logoBase64 = base64_encode(file_get_contents(public_path('images/logo.jpg'))))<div class="encabezado"><div class="numero">COMPROBANTE DE VENTA #{{ str_pad($venta->id_venta, 8, '0', STR_PAD_LEFT) }}</div><h1><img class="logo" src="data:image/jpeg;base64,{{ $logoBase64 }}">{{ config('farmacia.nombre') }}</h1>@if(config('farmacia.nit'))<div>NIT: {{ config('farmacia.nit') }}</div>@endif<div class="muted">Documento interno de venta</div></div><table class="datos"><tr><td><strong>Atendido por:</strong> {{ $venta->usuario->nombre }}</td><td><strong>Fecha:</strong> {{ $venta->fecha->format('d/m/Y H:i') }}</td></tr><tr><td><strong>Estado:</strong> Registrada</td></tr></table><table class="detalle"><thead><tr><th>Medicamento</th><th>Cantidad</th><th>Precio unitario</th><th>Subtotal</th></tr></thead><tbody>@foreach($venta->detalles as $detalle)<tr><td>{{ $detalle->medicamento->nombre }}</td><td>{{ $detalle->cantidad }}</td><td>Bs {{ number_format((float)$detalle->precio_unitario, 2) }}</td><td>Bs {{ number_format((float)$detalle->subtotal, 2) }}</td></tr>@endforeach</tbody></table><div class="total">Total: Bs {{ number_format((float)$venta->